package com.example.minicommerce.payment.infrastructure;
import com.example.minicommerce.payment.domain.PaymentStatus;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;
public interface PaymentAttemptRepository extends JpaRepository<PaymentAttemptEntity,UUID>{Optional<PaymentAttemptEntity>findByUserIdAndIdempotencyKey(Long userId,String key);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from PaymentAttemptEntity p where p.id=:id")Optional<PaymentAttemptEntity>findForUpdate(@Param("id")UUID id);@Modifying@Query(value="update payment_attempts set status='PROCESSING',processing_started_at=now(),updated_at=now(),version=version+1 where id=:id and (status='INITIATED' or (status='PROCESSING' and processing_started_at<:stale))",nativeQuery=true)int claim(@Param("id")UUID id,@Param("stale")Instant stale);}
